import type { Asset, AssetType, Scenario } from './types';
import universe from './universe.json';

/*
 * The 31 assets of the PolyFinances starter dataset, with REAL historical statistics computed from it
 * (adjusted closes from Yahoo Finance, CAD converted with the Bank of Canada rate, all in USD).
 * Generated by `python -m server.src.risk.build_front_data`; the descriptive texts below are written by hand.
 * Past figures describe what happened over the window; they are not forecasts.
 */

export const DATA_AS_OF: string = universe.as_of;
export const DATA_START: string = universe.start;
export const DATA_SOURCE: string = universe.source;

type Row = (typeof universe.assets)[number];

const TYPE: Record<string, AssetType> = {
  equity: 'stock',
  etf_equity: 'etf',
  etf_bond: 'bond',
  etf_commodity: 'other',
  crypto: 'other',
};

/** Starter sector labels -> the sector vocabulary of the profile form. */
const SECTOR: Record<string, string> = {
  'Information Technology': 'Technology',
  'Communication Services': 'Technology',
  'Health Care': 'Healthcare',
  'Consumer Discretionary': 'Consumer',
  'Consumer Staples': 'Consumer',
  Energy: 'Energy',
  Financials: 'Financials',
  Industrials: 'Industrials',
  Utilities: 'Utilities',
};

const region = (r: Row) => (r.asset_class === 'crypto' ? 'Global' : r.market === 'TSX' ? 'Canada' : 'United States');

function sectors(r: Row): string[] {
  if (r.asset_class === 'etf_equity') return ['Diversified'];
  if (r.asset_class === 'etf_bond') return ['Fixed income'];
  if (r.asset_class === 'etf_commodity') return ['Gold'];
  if (r.asset_class === 'crypto') return ['Crypto'];
  return [SECTOR[r.sector] ?? r.sector];
}

function typeLabel(r: Row): string {
  const where = region(r);
  return {
    equity: `Individual stock, ${where}`,
    etf_equity: `Equity ETF, ${where}`,
    etf_bond: `Bond ETF, ${where}`,
    etf_commodity: 'Gold ETF',
    crypto: 'Cryptoasset, trades 24/7',
  }[r.asset_class] ?? r.asset_class;
}

/** Qualitative role, fit and limitation, by asset class (written by hand, no figures). */
function texts(r: Row): Pick<Asset, 'role' | 'why' | 'limitation'> {
  if (r.asset_class === 'etf_bond')
    return {
      role: 'Stability and balance',
      why: 'Bonds may soften some stock-market movement.',
      limitation: 'Can lose value when interest rates rise, as in 2022.',
    };
  if (r.asset_class === 'etf_equity')
    return {
      role: r.ticker === 'ESGV' ? 'ESG-screened market exposure' : 'Broad market foundation',
      why: r.ticker === 'ESGV' ? 'Screens out some companies on ESG criteria.' : 'Spreads money across many companies at once.',
      limitation: 'Still moves with the whole stock market in a downturn.',
    };
  if (r.asset_class === 'etf_commodity')
    return { role: 'Diversifier', why: 'Gold often moves differently from stocks.', limitation: 'Produces no income and can stay flat for years.' };
  if (r.asset_class === 'crypto')
    return {
      role: 'Speculative growth',
      why: 'Can suit a long horizon and a high risk tolerance, in a small share.',
      limitation: 'Very large swings; no cash flows to anchor its value.',
    };
  return {
    role: `${sectors(r)[0]} company`,
    why: 'Direct exposure to one established business.',
    limitation: 'A single company: its own news can move the price sharply.',
  };
}

const BASE_WEIGHT: Record<string, number> = { equity: 5, etf_equity: 20, etf_bond: 20, etf_commodity: 5, crypto: 2 };

export const ASSETS: Asset[] = universe.assets.map((r) => ({
  ticker: r.ticker,
  name: r.name,
  type: TYPE[r.asset_class] ?? 'other',
  typeLabel: typeLabel(r),
  region: region(r),
  regions: [region(r)],
  currency: r.currency,
  sectors: sectors(r),
  keywords: [r.sector.toLowerCase(), r.asset_class.replace('_', ' '), ...(r.ticker === 'ESGV' ? ['esg'] : [])],
  ...texts(r),
  expReturn: r.return_ann,
  return1y: r.return_1y,
  vol: r.vol,
  mdd: -r.max_drawdown,
  expense: null, // not in the starter dataset
  baseWeight: BASE_WEIGHT[r.asset_class] ?? 5,
}));

/** Correlation of daily USD returns over the dataset (common trading days). */
export const CORRELATIONS: Record<string, Record<string, number>> = universe.correlations;

/** Initial selection on first arrival at Discover Assets (filtered by the profile). */
export const DEFAULT_SELECTION = ['SPY', 'XIU.TO', 'AGG', 'XBB.TO'];

/** Historical replays: what each asset actually did over a past window (not hypothetical moves). */
export const SCENARIOS: Scenario[] = universe.scenarios;
